    ? rows.map((r) => `${muted(`#${r.id} ${ago(r.created_at)} ${r.role ?? "—"} ${r.protocol_version ?? ""}`)}${r.went_well ? `\n  + ${r.went_well}` : ""}${r.friction ? `\n  − ${r.friction}` : ""}${r.suggestion ? `\n  → ${r.suggestion}` : ""}`).join("\n")
    : muted("no retros"));
  return EXIT.OK;
};

commands.metrics = async () => {
