const run = commands[command] ?? (command ? null : commands.help);
if (!run || flag("help")) {
  commands.help();
  process.exit(run || flag("help") ? EXIT.OK : EXIT.MISUSE);
}

try {
  process.exitCode = (await run()) ?? EXIT.OK;
} catch (error) {
  const code = error instanceof UsageError ? EXIT.MISUSE : EXIT.ERROR;
  const prefix = error instanceof MemoryError ? "memory" : error instanceof UsageError ? "usage" : "error";
  if (asJson) console.log(JSON.stringify({ ok: false, error: error.message }));
  else console.error(`${amber(`swarm ${prefix}:`)} ${error.message}`);
  process.exitCode = code;
}

// `.rallypoint/swarm.json`: what this swarm is for and how it is judged.
// Pure: parsing, defaults and validation only.

import { DEFAULT_ROLE_ORDER } from "./roles.mjs";
import { validateMeasure } from "./referee.mjs";

export const DEFAULTS = Object.freeze({
  goal: { title: "", statement: "", pitch: "" },
  measure: { mode: "review", label: "", command: "", direction: "higher", margin: 0, unit: "", checks: [], timeoutSeconds: 1800 },
  targets: [],
  ui: {
    project: { name: "", tagline: "" },
    targets: {},
    vocabulary: { shipped: "shipped", buried: "buried", version: "version" },
    includeUiTarget: false,
  },
  visibility: "public",
  protocolVersion: "p1",
  roleOrder: DEFAULT_ROLE_ORDER,
  improverRetroThreshold: 3,
  conductor: { concurrency: 4, budget: null, focus: "balanced", pace: "self" },
  tunablePaths: [".rallypoint/roles/", ".rallypoint/swarm/skills/", ".rallypoint/swarm/playbooks/"],
  frozenPaths: [
    ".rallypoint/scripts/",
    ".rallypoint/swarm/swarm.mjs",
    ".rallypoint/swarm/lib/",
    ".rallypoint/swarm/schema.sql",
    ".rallypoint/swarm/realtime.sql",
    ".rallypoint/swarm.json",
    ".rallypoint/roles/reviewer.md",
    ".rallypoint/roles/merger.md",
    ".rallypoint/roles/improver.md",
  ],
});

const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);

/** Shallow-per-section merge of a user config over the defaults. */
export const withDefaults = (config = {}) => ({
  ...DEFAULTS,
  ...config,
  goal: { ...DEFAULTS.goal, ...(config.goal ?? {}) },
  measure: { ...DEFAULTS.measure, ...(config.measure ?? {}) },
  ui: {
    ...DEFAULTS.ui,
    ...(config.ui ?? {}),
    project: { ...DEFAULTS.ui.project, ...(config.ui?.project ?? {}) },
    vocabulary: { ...DEFAULTS.ui.vocabulary, ...(config.ui?.vocabulary ?? {}) },
    targets: { ...(config.ui?.targets ?? {}) },
  },
  conductor: { ...DEFAULTS.conductor, ...(config.conductor ?? {}) },
  targets: Array.isArray(config.targets) ? config.targets : DEFAULTS.targets,
});

export const TARGET_ID = /^[a-z0-9][a-z0-9-]{0,39}$/;

/** @returns {string[]} problems; empty means valid */
export const validateSwarmConfig = (config) => {
  const problems = [];
  if (!isObject(config)) return [".rallypoint/swarm.json must be a JSON object"];
  problems.push(...validateMeasure(config.measure));
  const ids = new Set();
  for (const [i, target] of (config.targets ?? []).entries()) {
    if (!isObject(target) || !TARGET_ID.test(target.id ?? "")) {
      problems.push(`targets[${i}].id must match ${TARGET_ID} (lowercase, digits, dashes)`);
      continue;
    }
    if (ids.has(target.id)) problems.push(`targets[${i}].id "${target.id}" is duplicated`);
    ids.add(target.id);
  }
  if (!["public", "private"].includes(config.visibility)) problems.push('visibility must be "public" or "private"');
  const unknownRoles = (config.roleOrder ?? []).filter((role) => !DEFAULT_ROLE_ORDER.includes(role));
  if (unknownRoles.length) problems.push(`roleOrder has unknown role(s): ${unknownRoles.join(", ")}`);
  // A frozen file inside a tunable folder is fine (frozen wins, as in
  // vanilla: `.rallypoint/roles/` is tunable, `roles/reviewer.md` is not). A
  // tunable path inside a frozen one would hand the improver its own judge.
  for (const path of config.tunablePaths ?? []) {
    if ((config.frozenPaths ?? []).some((frozen) => path.startsWith(frozen))) {
      problems.push(`tunable path ${path} overlaps a frozen path`);
    }
  }
  return problems;
};

export const parseSwarmConfig = (text) => {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (error) {
    return { config: null, problems: [`.rallypoint/swarm.json is not valid JSON: ${error.message}`] };
  }
  const config = withDefaults(raw);
  return { config, problems: validateSwarmConfig(config) };
};

/** Everything a target can be, including the optional `ui` target. */
export const allTargets = (config) => {
  const targets = [...(config.targets ?? [])];
  if (config.ui?.includeUiTarget && !targets.some((target) => target.id === "ui")) {
    targets.push({ id: "ui", name: "UI", description: "The swarm's own frontend, grown from the Rallypoint scaffold." });
  }
  return targets;
};

import { spawnSync } from "node:child_process";
import { setTimeout as sleep } from "node:timers/promises";

const runCodex = (args, { cwd, input } = {}) => spawnSync("codex", args, {
  cwd,
  input,
  encoding: "utf8",
  timeout: 60_000,
  env: { ...process.env, NO_COLOR: "1" },
});

const taskUrlFrom = (stdout) => {
  const url = stdout?.trim();
  if (!/^https:\/\/[^\s/?#]+\/codex\/tasks\/[\w-]+$/.test(url ?? "")) return null;
  return url;
};

export const dispatchCodexCloud = async (
  { cwd, environment, branch, prompt, onSubmitted },
  { run = runCodex, wait = sleep } = {},
) => {
  const submission = run(
    ["cloud", "exec", "--env", environment, "--branch", branch, "--attempts", "1", "-"],
    { cwd, input: prompt },
  );
  const taskUrl = taskUrlFrom(submission.stdout);
  if (taskUrl) onSubmitted(taskUrl);
  if (submission.status !== 0 || !taskUrl) {
    if (submission.error?.code === "ENOENT") {
      throw new Error("Codex CLI was not found on PATH");
    }
    throw new Error(
      "Codex Cloud submission could not be confirmed. Check the Cloud task list before submitting again.",
    );
  }

  for (;;) {
    const result = run(["cloud", "status", taskUrl], { cwd });
    // Codex returns nonzero for PENDING, ERROR and APPLIED. Read the status
    // label first so a pending task continues to occupy its slot.
    const status = result.stdout?.match(/^\[(PENDING|READY|APPLIED|ERROR)\](?:\s|$)/m)?.[1];
    if (!result.error && status === "PENDING") {
      await wait(15_000);
      continue;
    }
    if (!result.error && (status === "READY" || status === "APPLIED" || status === "ERROR")) {
      return { taskUrl, status: status.toLowerCase() };
    }
    throw new Error(
      `Codex Cloud task status could not be confirmed. Keep the slot reserved and check ${taskUrl} before dispatching again.`,
    );
  }
};

// The swarm's memory: a zero-dependency client for the user's own Supabase
// project, over PostgREST. Reads use the publishable key; every write goes
// through a secret-checked RPC (see schema.sql). There is no other endpoint —
// nothing here talks to Rallypoint.

export class MemoryError extends Error {
  constructor(message, { status = null, code = null } = {}) {
    super(message);
    this.name = "MemoryError";
    this.status = status;
    this.code = code;
  }
}

/**
 * @param {{ url?: string, key?: string, secret?: string, fetchImpl?: typeof fetch }} options
 */
export const createMemory = ({ url, key, secret, fetchImpl = globalThis.fetch } = {}) => {
  const base = url ? String(url).replace(/\/+$/, "") : "";

  const configured = () => Boolean(base && key);
  const canWrite = () => configured() && Boolean(secret);

  const request = async (path, { method = "GET", body, headers = {} } = {}) => {
    if (!configured()) {
      throw new MemoryError("memory is not configured: set RALLYPOINT_SUPABASE_URL and RALLYPOINT_SUPABASE_KEY");
    }
    let response;
    try {
      response = await fetchImpl(`${base}/rest/v1/${path}`, {
        method,
        headers: {
          apikey: key,
          Authorization: `Bearer ${key}`,
          "Content-Type": "application/json",
          Accept: "application/json",
          ...headers,
        },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
    } catch (error) {
      throw new MemoryError(`could not reach ${base}: ${error.message}`);
    }
    const text = await response.text();
    let data = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = text;
    }
    if (!response.ok) {
      const message = (data && (data.message || data.hint || data.details)) || text || response.statusText;
      throw new MemoryError(`${method} ${path.split("?")[0]} failed (${response.status}): ${message}`, {
        status: response.status,
        code: data?.code ?? null,
      });
    }
    return data;
  };

  const rpc = (fn, args) => request(`rpc/${fn}`, { method: "POST", body: args });

  const requireSecret = () => {
    if (!secret) throw new MemoryError("writes need RALLYPOINT_SWARM_SECRET (agents only; never commit it)");
    return secret;
  };

  /**
   * @param {string} table
   * @param {{select?: string, order?: string, limit?: number, filters?: Record<string,string>}} query
   */
  // With the secret, read through `swarm_read` (works in private mode, where
  // RLS hides everything from the anon key). Without it, plain PostgREST.
  const select = (table, query = {}) =>
    secret
      ? rpc("swarm_read", {
          p_secret: secret,
          p_table: table,
          p_filters: query.filters ?? {},
          p_order: query.order ?? null,
          p_limit: query.limit ?? null,
        })
      : restSelect(table, query);

  const restSelect = (table, { select: columns = "*", order, limit, filters = {} } = {}) => {
    const params = new URLSearchParams({ select: columns });
    if (order) params.set("order", order);
    if (limit) params.set("limit", String(limit));
    for (const [column, condition] of Object.entries(filters)) params.append(column, condition);
    return request(`${table}?${params}`);
  };

  return {
    configured,
    canWrite,
    select,
    rpc,
    schemaVersion: () => rpc("swarm_schema_version", {}),
    // {publication: boolean, missing: string[]}: which memory tables the
    // dashboard cannot hear live yet (schema.sql, "Realtime").
    realtimeStatus: () => rpc("swarm_realtime_status", {}),
    check: () => rpc("swarm_check", { p_secret: requireSecret() }),
    insert: (table, row) => rpc("swarm_write", { p_secret: requireSecret(), p_table: table, p_row: row }),
    update: (table, id, patch) =>
      rpc("swarm_update", { p_secret: requireSecret(), p_table: table, p_id: String(id), p_patch: patch }),
    setSetting: (keyName, value) =>
      rpc("swarm_set_setting", { p_secret: requireSecret(), p_key: keyName, p_value: value }),
  };
};

export const memoryFromEnv = (env = process.env, fetchImpl) =>
  createMemory({
    url: env.RALLYPOINT_SUPABASE_URL,
    key: env.RALLYPOINT_SUPABASE_KEY,
    secret: env.RALLYPOINT_SWARM_SECRET,
    fetchImpl,
  });

// The referee: the measurement gate between "a pull request exists" and "it
// may be reviewed". It never approves anything — it records what the measure
// says, and review and merge stay independent.
//
// Three modes, because not every swarm has a reward function:
//   score  — a command prints a number; the candidate must beat the baseline
//            by `margin` in `direction`. (Swarm Arena: Elo against a ladder.)
//   checks — named commands must all exit 0 (build, tests, e2e, a budget
//            script). No number, no baseline run. (A website or product.)
//   review — nothing automated; independent review against the issue's
//            acceptance criteria is the gate. (Vanilla Rallypoint.)
//
// Everything here is pure except `runCommand`, which the caller injects.

export const MODES = ["score", "checks", "review"];

/**
 * Reads a score from command output: JSON `{"score": n}` on the last
 * non-empty line, or else the first number on that line.
 * @param {string} stdout
 * @returns {number|null}
 */
export const parseScore = (stdout) => {
  const lines = String(stdout ?? "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean);
  const last = lines.at(-1);
  if (!last) return null;
  try {
    const parsed = JSON.parse(last);
    if (parsed && typeof parsed === "object" && Number.isFinite(Number(parsed.score))) return Number(parsed.score);
    if (typeof parsed === "number" && Number.isFinite(parsed)) return parsed;
  } catch {
    // not JSON — fall through to the last token
  }
  // The FIRST number on the last line: "elo 1530 ± 40" is 1530, not the
  // error bar.
  const match = /[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/i.exec(last);
  return match ? Number(match[0]) : null;
};

/**
 * Compares a candidate score to a baseline.
 * @param {{candidate:number, baseline:number|null, direction?:"higher"|"lower", margin?:number}} input
 */
export const compareScores = ({ candidate, baseline, direction = "higher", margin = 0 }) => {
  if (!Number.isFinite(candidate)) return { passed: false, delta: null, reason: "the measure printed no score for the candidate" };
  if (baseline === null || baseline === undefined || !Number.isFinite(baseline)) {
    return { passed: true, delta: null, reason: "no baseline score yet: the first measured version sets it" };
  }
  const delta = direction === "lower" ? baseline - candidate : candidate - baseline;
  const passed = delta > (margin ?? 0);
  const word = direction === "lower" ? "lower" : "higher";
  return {
    passed,
    delta,
    reason: passed
      ? `candidate is ${Math.abs(delta)} ${word === "higher" ? "above" : "below"} the baseline (margin ${margin})`
      : `candidate does not beat the baseline by more than ${margin} (${word} is better; delta ${delta})`,
  };
};

/** Validates the `measure` block of `.rallypoint/swarm.json`. Returns a list of problems. */
export const validateMeasure = (measure) => {
  const problems = [];
  if (!measure || typeof measure !== "object") return ["measure is missing"];
  const mode = measure.mode ?? "review";
  if (!MODES.includes(mode)) problems.push(`measure.mode must be one of ${MODES.join(", ")}`);
  if (mode === "score") {
    if (!measure.command) problems.push("measure.command is required in score mode");
    if (!["higher", "lower"].includes(measure.direction ?? "higher")) problems.push('measure.direction must be "higher" or "lower"');
    if (measure.margin !== undefined && !Number.isFinite(Number(measure.margin))) problems.push("measure.margin must be a number");
  }
  if (mode === "checks") {
    const checks = measure.checks ?? [];
    if (!Array.isArray(checks) || checks.length === 0) problems.push("measure.checks needs at least one {name, command} in checks mode");
    for (const [i, check] of (Array.isArray(checks) ? checks : []).entries()) {
      if (!check?.name || !check?.command) problems.push(`measure.checks[${i}] needs a name and a command`);
    }
  }
  return problems;
};

/**
 * Runs the configured measure and returns the record to store in
 * `swarm_results`, without storing it.
 *
 * @param {{
 *   measure: any,
 *   runCommand: (command: string, options: {cwd: string, timeoutSeconds: number}) => {status:number|null, stdout:string, stderr:string, durationMs:number},
 *   cwd: string,
 *   baselineCwd?: string|null,
 *   requireBaseline?: boolean,
 * }} input
 *
 * Score mode fails closed: when a baseline is required (the default) and it
 * could not be measured, the candidate does not pass. Only the very first
 * measured version may skip it, explicitly (`requireBaseline: false`).
 */
export const referee = ({ measure, runCommand, cwd, baselineCwd = null, requireBaseline = true }) => {
  const mode = measure?.mode ?? "review";
  const timeoutSeconds = Number(measure?.timeoutSeconds ?? 1800);

  if (mode === "review") {
    return {
      mode,
      passed: true,
      candidate_score: null,
      baseline_score: null,
      delta: null,
      reason: "review mode: nothing automated to measure; the independent review is the gate",
      details: { mode },
    };
  }

  if (mode === "checks") {
    const checks = (measure.checks ?? []).map((check) => {
      const run = runCommand(check.command, { cwd, timeoutSeconds });
      return {
        name: check.name,
        command: check.command,
        passed: run.status === 0,
        exitCode: run.status,
        durationMs: run.durationMs,
        tail: tail(run.status === 0 ? run.stdout : `${run.stdout}\n${run.stderr}`),
      };
    });
    const failed = checks.filter((check) => !check.passed).map((check) => check.name);
    return {
      mode,
      passed: failed.length === 0,
      candidate_score: null,
      baseline_score: null,
      delta: null,
      reason: failed.length ? `failed: ${failed.join(", ")}` : `all ${checks.length} checks passed`,
      details: { mode, checks },
    };
  }

  const direction = measure.direction ?? "higher";
  const margin = Number(measure.margin ?? 0);
  const candidateRun = runCommand(measure.command, { cwd, timeoutSeconds });
  const candidate = candidateRun.status === 0 ? parseScore(candidateRun.stdout) : null;
  let baseline = null;
  let baselineRun = null;
  if (baselineCwd) {
    baselineRun = runCommand(measure.command, { cwd: baselineCwd, timeoutSeconds });
    baseline = baselineRun.status === 0 ? parseScore(baselineRun.stdout) : null;
  }
  const verdict =
    candidateRun.status !== 0
      ? { passed: false, delta: null, reason: `the measure exited ${candidateRun.status} on the candidate` }
      : requireBaseline && baseline === null
        ? {
            passed: false,
            delta: null,
            reason: baselineRun
              ? `the baseline could not be measured (exit ${baselineRun.status}); nothing to beat, so nothing passes`
              : "no baseline was available to measure; pass --first only for the very first version",
          }
        : compareScores({ candidate, baseline, direction, margin });
  return {
    mode,
    passed: verdict.passed,
    candidate_score: candidate,
    baseline_score: baseline,
    delta: verdict.delta,
    reason: verdict.reason,
    details: {
      mode,
      unit: measure.unit ?? null,
      direction,
      margin,
      candidate: { exitCode: candidateRun.status, durationMs: candidateRun.durationMs, tail: tail(candidateRun.stdout) },
      baseline: baselineRun
        ? { exitCode: baselineRun.status, durationMs: baselineRun.durationMs, tail: tail(baselineRun.stdout) }
        : null,
    },
  };
};

const tail = (text, lines = 12) => String(text ?? "").trimEnd().split(/\r?\n/).slice(-lines).join("\n");

// Role selection for a swarm session. Pure: no GitHub, no network, no clock.
//
// A new session takes the FIRST role in `roleOrder` that has something
// waiting. Finishing work beats starting it, so the default order empties the
// right-hand side of the board first:
//
//   merger → fixer → reviewer → improver → worker → planner → janitor
//
// `queues` counts what waits for each role. `computeQueues` derives it from
// the open pull requests and issues (as `gh --json` returns them), the
// coordination report, and the memory's metrics.

export const DEFAULT_ROLE_ORDER = [
  "merger",
  "fixer",
  "reviewer",
  "improver",
  "worker",
  "planner",
  "janitor",
];

export const ROLE_WHEN = {
  merger: "a pull request has an independent approve",
  fixer: "a review asked for changes",
  reviewer: "a pull request waits for a verdict",
  improver: "enough retros have landed since the last protocol change",
  worker: "a claimable issue is open",
  planner: "nothing claimable is open",
  janitor: "claims, leases or labels disagree",
};

const HOLD_LABELS = (labels) => [
  labels.claimed ?? "status:claimed",
  labels.blocked ?? "status:blocked",
  labels.deferred ?? "status:deferred",
  labels.human ?? "needs:human",
];

const JANITOR_KINDS = new Set([
  "unclaimable",
  "unprotected",
  "janitorCandidate",
  "assigneeDrift",
  "closedWithStatusLabel",
  "blockedWithClearedDependencies",
]);

const names = (item) => (item.labels ?? []).map((label) => (typeof label === "string" ? label : label.name));

const PRIORITY = (item) => {
  const match = names(item).map((name) => /^prio:p(\d)$/.exec(name)).find(Boolean);
  return match ? Number(match[1]) : 9;
};

const CLOSES = /\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?|refs?)\s+#(\d+)/gi;

/** Issue numbers a pull request body points at. */
export const referencedIssues = (body = "") =>
  [...String(body).matchAll(CLOSES)].map((match) => Number(match[1]));

/**
 * Whether an issue or pull request belongs to `target`. With no target every
 * item matches. A pull request matches through its own `target:` label or
 * through an issue it closes.
 */
export const inTarget = (item, target, issuesByNumber = new Map()) => {
  if (!target) return true;
  const label = `target:${target}`;
  if (names(item).includes(label)) return true;
  return referencedIssues(item.body).some((n) => names(issuesByNumber.get(n) ?? {}).includes(label));
};

/**
 * @param {{
 *   pulls: Array<{number:number,title?:string,labels?:any[],isDraft?:boolean,body?:string}>,
 *   issues: Array<{number:number,title?:string,labels?:any[],assignees?:any[]}>,
 *   labels?: Record<string,string>,
 *   target?: string|null,
 *   retrosSinceChange?: number|null,
 *   improverRetroThreshold?: number,
 *   improvementOpen?: boolean,
 *   disagreements?: Array<{kind:string}>|null,
 * }} input
 */
export const computeQueues = ({
  pulls,
  issues,
  labels = {},
  target = null,
  retrosSinceChange = 0,
  improverRetroThreshold = 3,
  improvementOpen = false,
  disagreements = [],
}) => {
  const approved = labels.approved ?? "review:approved";
  const changes = labels.changesRequested ?? "status:changes-requested";
  const holds = HOLD_LABELS(labels);
  const issuesByNumber = new Map(issues.map((issue) => [issue.number, issue]));

  const openPulls = pulls.filter((pr) => !pr.isDraft && inTarget(pr, target, issuesByNumber));
  const mergeable = openPulls.filter((pr) => names(pr).includes(approved));
  const fixable = openPulls.filter((pr) => names(pr).includes(changes));
  const reviewable = openPulls.filter((pr) => !names(pr).includes(approved) && !names(pr).includes(changes));

  const scoped = issues.filter((issue) => inTarget(issue, target));
  const claimable = scoped
    .filter((issue) => !names(issue).some((name) => holds.includes(name)))
    .filter((issue) => (issue.assignees ?? []).length === 0)
    .sort((a, b) => PRIORITY(a) - PRIORITY(b) || a.number - b.number);

  const improverDue = !improvementOpen && (retrosSinceChange ?? 0) >= improverRetroThreshold;
  const janitorItems = (disagreements ?? []).filter((item) => JANITOR_KINDS.has(item.kind));

  const byOldest = (a, b) => a.number - b.number;
  return {
    merger: { count: mergeable.length, next: mergeable.sort(byOldest)[0] ?? null, kind: "pr" },
    fixer: { count: fixable.length, next: fixable.sort(byOldest)[0] ?? null, kind: "pr" },
    reviewer: { count: reviewable.length, next: reviewable.sort(byOldest)[0] ?? null, kind: "pr" },
    improver: { count: improverDue ? 1 : 0, next: null, kind: null },
    worker: { count: claimable.length, next: claimable[0] ?? null, kind: "issue" },
    planner: { count: scoped.length === 0 ? 1 : 0, next: null, kind: null },
    janitor: { count: janitorItems.length, next: null, kind: null },
  };
};

/**
 * Picks the first role in `order` (optionally restricted to `only`) whose
 * queue is non-empty. Returns null when nothing waits.
 */
export const pickRole = ({ queues, order = DEFAULT_ROLE_ORDER, only = null }) => {
  const allowed = only && only.length ? order.filter((role) => only.includes(role)) : order;
  for (const role of allowed) {
    const queue = queues[role];
    if (queue && queue.count > 0) return { role, ...queue };
  }
  return null;
};

// Generates the project's own `app/swarm/swarm.config.ts` from
// `.rallypoint/swarm.json`. Pure. The mapping is the one documented at the top
// of the scaffold's `app/swarm/_lib/config-types.ts`; keep the two in step.
//
// The generated file is project-owned: the CLI writes it only when absent.

import { allTargets, withDefaults } from "./config.mjs";

export const DEFAULT_TARGET_COLORS = ["#2f5bd3", "#d4572a", "#0f8a6a", "#a23dbf", "#b8860b", "#2a7fb8", "#c0396b", "#5b6b2f"];

const MEASURE_LABEL = { score: "Score", checks: "Checks", review: "Review" };

const capital = (text) => (text ? text[0].toUpperCase() + text.slice(1) : text);

/** The swarmConfig object the generated file exports (minus nav/vocabulary spreads). */
export const uiConfigFrom = (rawConfig, { repository = null } = {}) => {
  const config = withDefaults(rawConfig);
  const repoName = repository ? String(repository).split("/").pop() : "";
  const mode = config.measure.mode ?? "review";
  return {
    project: {
      name: config.ui.project.name || repoName || "Swarm",
      tagline: config.ui.project.tagline || config.goal.pitch || "",
    },
    goal: { title: config.goal.title ?? "", statement: config.goal.statement ?? "" },
    measure: {
      mode,
      label: config.measure.label || MEASURE_LABEL[mode] || "Review",
      unit: config.measure.unit ?? "",
      direction: config.measure.direction === "lower" ? "lower" : "higher",
    },
    targets: allTargets(config).map((target, i) => ({
      id: target.id,
      name: target.name || target.id,
      color: config.ui.targets?.[target.id]?.color || DEFAULT_TARGET_COLORS[i % DEFAULT_TARGET_COLORS.length],
      description: target.description ?? "",
    })),
    vocabulary: rawConfig?.ui?.vocabulary ?? {},
  };
};

const literal = (value, indent = 2) =>
  JSON.stringify(value, null, 2)
    .split("\n")
    .map((line, i) => (i === 0 ? line : `${" ".repeat(indent)}${line}`))
    .join("\n");

/** @returns {string} TypeScript source for app/swarm/swarm.config.ts */
export const renderUiConfig = (rawConfig, options = {}) => {
  const ui = uiConfigFrom(rawConfig, options);
  const vocabulary = Object.fromEntries(Object.entries(ui.vocabulary).filter(([, value]) => typeof value === "string" && value));
  const navOverrides = {};
  if (vocabulary.targets) navOverrides["/swarm/targets"] = capital(vocabulary.targets);
  if (vocabulary.results) navOverrides["/swarm/results"] = capital(vocabulary.results);
  const nav = Object.keys(navOverrides).length
    ? `DEFAULT_NAV.map((item) => ({ ...item, label: (${literal(navOverrides, 4)} as Record<string, string>)[item.href] ?? item.label }))`
    : "[...DEFAULT_NAV]";

  return `/**
 * Swarm UI configuration for ${ui.project.name}. This file is PROJECT-OWNED:
 * edit freely. Rallypoint wrote it once, from .rallypoint/swarm.json, and never
 * overwrites it (regenerate on purpose with: npx rallypoint swarm ui-config --force).
 *
 * It holds every project-specific word, colour and route the swarm pages print.
 * The field-by-field mapping is documented at the top of ./_lib/config-types.ts.
 */
import {
  DEFAULT_NAV,
  DEFAULT_VOCABULARY,
  type SwarmConfig,
} from "./_lib/config-types";

export const swarmConfig: SwarmConfig = {
  project: ${literal(ui.project)},
  goal: ${literal(ui.goal)},
  measure: ${literal(ui.measure)},
  targets: ${literal(ui.targets)},
  vocabulary: { ...DEFAULT_VOCABULARY${Object.keys(vocabulary).length ? `, ...${literal(vocabulary, 2)}` : ""} },
  nav: ${nav},
  theme: {
    cssVars: {},
  },
};
`;
};

-- Rallypoint Swarm — shared memory schema (schema version 1).
--
-- Apply once to YOUR OWN Supabase project: paste into the SQL editor, or run
--   psql "$DATABASE_URL" -f .rallypoint/swarm/schema.sql
-- It is idempotent: re-running it upgrades in place and keeps your data.
--
-- Then set the agents' write secret (at least 16 characters) with
--   npx rallypoint swarm connect
-- which prompts for it, sets it with the service-role key and writes the
-- gitignored env files. Or, in the SQL editor:
--   select public.swarm_set_secret('a-long-random-secret');
-- and give that same value to agents as RALLYPOINT_SWARM_SECRET.
--
-- Model
--   * GitHub owns the work (issues, claims, pull requests, reviews, merges).
--     This database owns the memory: sessions, progress, retros, messages,
--     referee results, shipped versions, buried ideas, concepts.
--   * The memory tables are in the supabase_realtime publication, so the
--     dashboard updates live. Realtime honours the same RLS (see "Realtime").
--   * Everyone allowed to read reads through RLS (public, or signed-in when
--     visibility is "private"). Nobody writes through tables: there are no
--     insert/update/delete policies.
--   * Agents write only through the SECURITY DEFINER functions below, each of
--     which first checks the swarm secret against a bcrypt hash.
--   * Nothing here calls Rallypoint. There is no Rallypoint server.

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table if not exists public.swarm_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

-- Single-row secret store. Never readable by anon/authenticated.
create table if not exists public.swarm_secret (
  id int primary key default 1 check (id = 1),
  hash text not null,
  updated_at timestamptz not null default now()
);

-- Optional allow-list for private mode. Empty = any signed-in user may read.
create table if not exists public.swarm_readers (
  email text primary key,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_sessions (
  id uuid primary key default gen_random_uuid(),
  agent text not null,
  role text,
  target text,
  issue int,
  pr int,
  status text not null default 'working'
    check (status in ('working', 'ended', 'abandoned')),
  summary text,
  started_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  ended_at timestamptz
);

create table if not exists public.swarm_progress (
  id bigint generated always as identity primary key,
  session_id uuid not null references public.swarm_sessions (id) on delete cascade,
  note text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_retros (
  id bigint generated always as identity primary key,
  session_id uuid references public.swarm_sessions (id) on delete set null,
  role text,
  protocol_version text,
  went_well text,
  friction text,
  suggestion text,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_messages (
  id bigint generated always as identity primary key,
  thread_id bigint references public.swarm_messages (id) on delete cascade,
  session_id uuid references public.swarm_sessions (id) on delete set null,
  author text not null,
  kind text not null default 'note'
    check (kind in ('question', 'proposal', 'handoff', 'answer', 'note')),
  ref text,
  topic text,
  body text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_results (
  id bigint generated always as identity primary key,
  session_id uuid references public.swarm_sessions (id) on delete set null,
  target text,
  issue int,
  pr int,
  commit_sha text,
  baseline_sha text,
  mode text not null default 'score' check (mode in ('score', 'checks', 'review')),
  candidate_score double precision,
  baseline_score double precision,
  delta double precision,
  direction text check (direction in ('higher', 'lower')),
  margin double precision,
  passed boolean not null,
  details jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_versions (
  id bigint generated always as identity primary key,
  target text,
  version text not null,
  score double precision,
  pr int,
  commit_sha text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_buried (
  id bigint generated always as identity primary key,
  target text,
  issue int,
  pr int,
  idea text not null,
  concept text,
  reason text not null,
  lesson text,
  numbers jsonb,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_concepts (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9-]*$'),
  name text not null,
  description text,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_concept_trials (
  id bigint generated always as identity primary key,
  concept_id text not null references public.swarm_concepts (id) on delete cascade,
  target text not null,
  outcome text not null check (outcome in ('gained', 'lost', 'neutral')),
  delta double precision,
  ref text,
  created_at timestamptz not null default now()
);

create table if not exists public.swarm_protocol_changes (
  id bigint generated always as identity primary key,
  version text not null,
  issue int,
  pr int,
  summary text not null,
  kept boolean,
  created_at timestamptz not null default now()
);

-- Upgrades from earlier drafts of schema version 1.
alter table public.swarm_results add column if not exists mode text not null default 'score';

create index if not exists swarm_sessions_status_idx on public.swarm_sessions (status, last_seen_at desc);
create index if not exists swarm_progress_session_idx on public.swarm_progress (session_id, created_at desc);
create index if not exists swarm_retros_created_idx on public.swarm_retros (created_at desc);
create index if not exists swarm_messages_created_idx on public.swarm_messages (created_at desc);
create index if not exists swarm_messages_thread_idx on public.swarm_messages (thread_id);
create index if not exists swarm_results_created_idx on public.swarm_results (created_at desc);
create index if not exists swarm_versions_target_idx on public.swarm_versions (target, created_at desc);
create index if not exists swarm_buried_created_idx on public.swarm_buried (created_at desc);
create index if not exists swarm_trials_concept_idx on public.swarm_concept_trials (concept_id, target);

insert into public.swarm_settings (key, value) values
  ('visibility', '"public"'),
  ('protocol_version', '"p1"')
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- Read access
-- ---------------------------------------------------------------------------

-- search_path is pinned on every function, including these two that touch no
-- table, so Supabase's security advisor (function_search_path_mutable) has
-- nothing to report on a fresh project.
create or replace function public.swarm_schema_version()
returns int language sql immutable set search_path = '' as $$ select 1 $$;

create or replace function public.swarm_can_read()
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  visibility text;
  v_email text;
begin
  select value #>> '{}' into visibility from public.swarm_settings where key = 'visibility';
  if coalesce(visibility, 'public') = 'public' then
    return true;
  end if;
  if coalesce(auth.role(), '') <> 'authenticated' then
    return false;
  end if;
  if not exists (select 1 from public.swarm_readers) then
    return true;
  end if;
  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  return exists (select 1 from public.swarm_readers r where lower(r.email) = v_email);
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'swarm_settings', 'swarm_sessions', 'swarm_progress', 'swarm_retros',
    'swarm_messages', 'swarm_results', 'swarm_versions', 'swarm_buried',
    'swarm_concepts', 'swarm_concept_trials', 'swarm_protocol_changes'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists swarm_read on public.%I', t);
    execute format(
      'create policy swarm_read on public.%I for select to anon, authenticated using (public.swarm_can_read())',
      t
    );
    execute format('revoke insert, update, delete, truncate on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to anon, authenticated', t);
  end loop;
end;
$$;

-- The secret and the reader list are never exposed.
alter table public.swarm_secret enable row level security;
alter table public.swarm_readers enable row level security;
revoke all on public.swarm_secret from anon, authenticated;
revoke all on public.swarm_readers from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Views
-- ---------------------------------------------------------------------------

create or replace view public.swarm_fleet
with (security_invoker = true) as
select
  s.id,
  s.agent,
  s.role,
  s.target,
  s.issue,
  s.pr,
  s.started_at,
  s.last_seen_at,
  p.note as latest_note,
  p.created_at as latest_note_at
from public.swarm_sessions s
left join lateral (
  select note, created_at
  from public.swarm_progress
  where session_id = s.id
  order by created_at desc
  limit 1
) p on true
where s.status = 'working'
  and s.last_seen_at > now() - interval '2 hours'
order by s.last_seen_at desc;

-- "Claim to close" is measured on worker sessions: from the session opening
-- (just before the claim) to its end (pull request submitted or released).
create or replace view public.swarm_metrics
with (security_invoker = true) as
with
  last_change as (
    select max(created_at) as at from public.swarm_protocol_changes
  ),
  counts as (
    select
      (select count(*) from public.swarm_versions) as shipped,
      (select count(*) from public.swarm_buried) as buried,
      (select count(*) from public.swarm_sessions) as sessions,
      (select count(*) from public.swarm_progress) as progress,
      (select count(*) from public.swarm_sessions
         where status = 'working' and last_seen_at > now() - interval '2 hours') as working
  )
select
  coalesce((select value #>> '{}' from public.swarm_settings where key = 'protocol_version'), 'p1')
    as protocol_version,
  c.shipped,
  c.buried,
  case when c.shipped + c.buried = 0 then null
       else round(c.shipped::numeric / (c.shipped + c.buried), 4) end as ship_rate,
  (select round((percentile_cont(0.5) within group (
       order by extract(epoch from (ended_at - started_at)) / 60.0))::numeric, 1)
     from public.swarm_sessions
     where role = 'worker' and ended_at is not null) as median_claim_to_close_minutes,
  case when c.sessions = 0 then null
       else round(c.progress::numeric / c.sessions, 2) end as progress_per_session,
  (select count(*) from public.swarm_retros r, last_change l
     where l.at is null or r.created_at > l.at) as retros_since_change,
  c.working as sessions_working
from counts c;

grant select on public.swarm_fleet, public.swarm_metrics to anon, authenticated;

-- ---------------------------------------------------------------------------
-- Realtime (live dashboard)
-- ---------------------------------------------------------------------------

-- >>> realtime (kept identical in schema.sql and realtime.sql; scripts/test-swarm.mjs checks)
--
-- The dashboard subscribes to changes on these tables and re-renders the page
-- it shows, so it updates without a reload. It never reads the change payload:
-- every page re-reads through PostgREST, which stays the source of truth.
--
-- Privacy: Realtime applies the tables' RLS to postgres_changes, per
-- subscriber, with the subscriber's own token. The `swarm_read` policy above
-- therefore decides who hears a change exactly as it decides who reads the
-- row: in private mode only signed-in readers on the allow-list receive
-- events and the anon key receives none. swarm_secret, swarm_readers and
-- swarm_settings are never published.
--
-- Idempotent, and safe off Supabase: `alter publication ... add table` errors
-- when the table is already a member (or the publication is FOR ALL TABLES),
-- and plain Postgres has no supabase_realtime publication, so both are
-- checked first. Without the publication the dashboard polls once a minute.

create or replace function public.swarm_realtime_wanted()
returns text[] language sql immutable set search_path = '' as $$
  select array[
    'swarm_sessions', 'swarm_progress', 'swarm_retros', 'swarm_messages',
    'swarm_results', 'swarm_versions', 'swarm_buried', 'swarm_concepts',
    'swarm_concept_trials', 'swarm_protocol_changes'
  ]
$$;

-- What `swarm doctor` asks: is the publication there, and which of the
-- wanted tables are not in it yet. Reveals table names only.
create or replace function public.swarm_realtime_status()
returns jsonb
language sql
stable
set search_path = public, pg_catalog
as $$
  select jsonb_build_object(
    'publication', exists (select 1 from pg_publication where pubname = 'supabase_realtime'),
    'missing', coalesce((
      select jsonb_agg(t order by t)
      from unnest(public.swarm_realtime_wanted()) t
      where not exists (
        select 1 from pg_publication_tables p
        where p.pubname = 'supabase_realtime' and p.schemaname = 'public' and p.tablename = t
      )
    ), '[]'::jsonb)
  )
$$;

do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    raise notice 'no supabase_realtime publication here: skipping (the swarm dashboard will poll instead)';
    return;
  end if;
  foreach t in array public.swarm_realtime_wanted() loop
    if not exists (
      select 1 from pg_publication_tables p
      where p.pubname = 'supabase_realtime' and p.schemaname = 'public' and p.tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end;
$$;

grant execute on function public.swarm_realtime_wanted() to anon, authenticated;
grant execute on function public.swarm_realtime_status() to anon, authenticated;
-- <<< realtime

-- ---------------------------------------------------------------------------
-- Writes (agents only, via the swarm secret)
-- ---------------------------------------------------------------------------

create or replace function public.swarm_set_secret(p_secret text)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  if p_secret is null or length(p_secret) < 16 then
    raise exception 'the swarm secret must be at least 16 characters';
  end if;
  insert into public.swarm_secret (id, hash, updated_at)
  values (1, extensions.crypt(p_secret, extensions.gen_salt('bf', 10)), now())
  on conflict (id) do update set hash = excluded.hash, updated_at = now();
end;
$$;

create or replace function public.swarm_assert_secret(p_secret text)
returns void
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
declare
  stored text;
begin
  select hash into stored from public.swarm_secret where id = 1;
  if stored is null then
    raise exception 'no swarm secret is set; run npx rallypoint swarm connect, or select public.swarm_set_secret(''…'') in the SQL editor'
      using errcode = '28000';
  end if;
  if p_secret is null or extensions.crypt(p_secret, stored) <> stored then
    raise exception 'invalid swarm secret' using errcode = '28P01';
  end if;
end;
$$;

create or replace function public.swarm_writable(p_table text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select p_table = any (array[
    'swarm_sessions', 'swarm_progress', 'swarm_retros', 'swarm_messages',
    'swarm_results', 'swarm_versions', 'swarm_buried', 'swarm_concepts',
    'swarm_concept_trials', 'swarm_protocol_changes'
  ])
$$;

create or replace function public.swarm_write(p_secret text, p_table text, p_row jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  cols text;
  bad text;
  result jsonb;
begin
  perform public.swarm_assert_secret(p_secret);
  if not public.swarm_writable(p_table) then
    raise exception 'table % is not writable', p_table using errcode = '42501';
  end if;
  if p_row is null or jsonb_typeof(p_row) <> 'object' or p_row = '{}'::jsonb then
    raise exception 'row must be a non-empty JSON object' using errcode = '22023';
  end if;

  -- Only real, non-generated columns may be written.
  select string_agg(k, ', ') into bad
  from jsonb_object_keys(p_row) k
  where not exists (
    select 1 from information_schema.columns c
    where c.table_schema = 'public' and c.table_name = p_table
      and c.column_name = k and c.is_identity = 'NO'
  );
  if bad is not null then
    raise exception 'unknown or generated column(s) for %: %', p_table, bad using errcode = '42703';
  end if;

  select string_agg(format('%I', k), ', ') into cols from jsonb_object_keys(p_row) k;
  execute format(
    'insert into public.%1$I as t (%2$s) select %2$s from jsonb_populate_record(null::public.%1$I, $1) returning to_jsonb(t.*)',
    p_table, cols
  ) into result using p_row;
  return result;
end;
$$;

create or replace function public.swarm_update(p_secret text, p_table text, p_id text, p_patch jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  allowed text[];
  bad text;
  sets text;
  id_type text;
  result jsonb;
begin
  perform public.swarm_assert_secret(p_secret);
  allowed := case p_table
    when 'swarm_sessions' then array['agent', 'role', 'target', 'issue', 'pr', 'status', 'summary', 'last_seen_at', 'ended_at']
    when 'swarm_protocol_changes' then array['issue', 'pr', 'summary', 'kept']
    when 'swarm_concepts' then array['name', 'description']
    else null
  end;
  if allowed is null then
    raise exception 'table % is not updatable', p_table using errcode = '42501';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' or p_patch = '{}'::jsonb then
    raise exception 'patch must be a non-empty JSON object' using errcode = '22023';
  end if;
  select string_agg(k, ', ') into bad from jsonb_object_keys(p_patch) k where not (k = any (allowed));
  if bad is not null then
    raise exception 'column(s) not updatable on %: %', p_table, bad using errcode = '42501';
  end if;

  select string_agg(format('%1$I = r.%1$I', k), ', ') into sets from jsonb_object_keys(p_patch) k;
  id_type := case p_table when 'swarm_sessions' then 'uuid' when 'swarm_concepts' then 'text' else 'bigint' end;
  execute format(
    'update public.%1$I as t set %2$s from jsonb_populate_record(null::public.%1$I, $1) r where t.id = $2::%3$s returning to_jsonb(t.*)',
    p_table, sets, id_type
  ) into result using p_patch, p_id;
  if result is null then
    raise exception 'no % row with id %', p_table, p_id using errcode = 'P0002';
  end if;
  return result;
end;
$$;

create or replace function public.swarm_set_setting(p_secret text, p_key text, p_value jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  perform public.swarm_assert_secret(p_secret);
  if p_key not in ('visibility', 'protocol_version', 'goal', 'targets', 'ui') then
    raise exception 'setting % is not writable', p_key using errcode = '42501';
  end if;
  if p_key = 'visibility' and (p_value #>> '{}') not in ('public', 'private') then
    raise exception 'visibility must be "public" or "private"' using errcode = '22023';
  end if;
  insert into public.swarm_settings (key, value, updated_at) values (p_key, p_value, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  return jsonb_build_object('key', p_key, 'value', p_value);
end;
$$;

-- Agents read through this when the swarm is private: RLS hides every table
-- from the anon key then, and agents must still see their own memory.
-- Filters are {"column": "eq.value" | "gt.value"} on real columns only.
create or replace function public.swarm_read(
  p_secret text,
  p_table text,
  p_filters jsonb default '{}'::jsonb,
  p_order text default null,
  p_limit int default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
declare
  conditions text := '';
  col text;
  cond text;
  op text;
  order_sql text := '';
  result jsonb;
begin
  perform public.swarm_assert_secret(p_secret);
  if not (public.swarm_writable(p_table) or p_table in ('swarm_settings', 'swarm_fleet', 'swarm_metrics')) then
    raise exception 'table % is not readable', p_table using errcode = '42501';
  end if;
  for col, cond in select key, value #>> '{}' from jsonb_each(coalesce(p_filters, '{}'::jsonb)) loop
    if not exists (
      select 1 from information_schema.columns c
      where c.table_schema = 'public' and c.table_name = p_table and c.column_name = col
    ) then
      raise exception 'unknown column % on %', col, p_table using errcode = '42703';
    end if;
    op := split_part(cond, '.', 1);
    if op not in ('eq', 'gt') then
      raise exception 'filter % must be eq.<value> or gt.<value>', col using errcode = '22023';
    end if;
    conditions := conditions || format(
      ' and %I::text %s %L',
      col,
      case op when 'eq' then '=' else '>' end,
      substr(cond, length(op) + 2)
    );
  end loop;
  if p_order is not null then
    col := split_part(p_order, '.', 1);
    if not exists (
      select 1 from information_schema.columns c
      where c.table_schema = 'public' and c.table_name = p_table and c.column_name = col
    ) then
      raise exception 'unknown order column % on %', col, p_table using errcode = '42703';
    end if;
    order_sql := format(' order by %I %s', col, case when p_order like '%.desc' then 'desc' else 'asc' end);
  end if;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select * from public.%I where true%s%s%s) t',
    p_table,
    conditions,
    order_sql,
    case when p_limit is not null then format(' limit %s', greatest(p_limit, 0)) else '' end
  ) into result;
  return result;
end;
$$;

create or replace function public.swarm_check(p_secret text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  perform public.swarm_assert_secret(p_secret);
  return jsonb_build_object('ok', true, 'schema_version', public.swarm_schema_version());
end;
$$;

-- Function privileges: everything is revoked from PUBLIC first, then only
-- the secret-checked RPCs and read helpers are granted.
revoke all on function public.swarm_set_secret(text) from public, anon, authenticated;
-- service_role is the project's admin key; `rallypoint swarm connect` uses it
-- once to set the secret over the API instead of the SQL editor.
grant execute on function public.swarm_set_secret(text) to service_role;
revoke all on function public.swarm_assert_secret(text) from public, anon, authenticated;
revoke all on function public.swarm_write(text, text, jsonb) from public;
revoke all on function public.swarm_update(text, text, text, jsonb) from public;
revoke all on function public.swarm_set_setting(text, text, jsonb) from public;
revoke all on function public.swarm_check(text) from public;
revoke all on function public.swarm_read(text, text, jsonb, text, int) from public;
grant execute on function public.swarm_read(text, text, jsonb, text, int) to anon, authenticated;
grant execute on function public.swarm_write(text, text, jsonb) to anon, authenticated;
grant execute on function public.swarm_update(text, text, text, jsonb) to anon, authenticated;
grant execute on function public.swarm_set_setting(text, text, jsonb) to anon, authenticated;
grant execute on function public.swarm_check(text) to anon, authenticated;
grant execute on function public.swarm_schema_version() to anon, authenticated;
grant execute on function public.swarm_can_read() to anon, authenticated;
grant execute on function public.swarm_writable(text) to anon, authenticated;
